public static long knapsack(int N, int MAX, int[] weight, long[] worth) {
    if (N == 0) {
        return 0;
    }
    long dp[][] = new long[N][MAX+1];
    for (int i=0; i<=MAX; i++) {
        dp[0][i] = -1;
    }
    dp[0][0] = 0;
    if (weight[0] <= MAX) {
        dp[0][weight[0]] = worth[0];
    }
    for (int i=1; i<N; i++) {
        int wei = weight[i];
        long wor = worth[i];
        for (int s=0; s<=MAX; s++) {
            dp[i][s] = dp[i-1][s];
        }
        for (int s=0; s<=MAX; s++) {
            if (dp[i-1][s] != -1) {
                if (s + wei <= MAX && dp[i-1][s] + wor > dp[i][s+wei]) {
                    dp[i][s+wei] = dp[i-1][s] + wor; // Fixed the bug by adding the condition to ensure the new worth is greater.
                }
            }
        }
    }
    long max_worth = 0;
    for (int i=0; i<=MAX; i++) {
        if (max_worth < dp[N-1][i]) {
            max_worth = dp[N-1][i];
        }
    }
    return max_worth;
}
